// Regression tests for Prompt 17 — the admin order detail page.
//
// These tests cover the 12 scenarios listed in Prompt 17 §8:
//
//   1. A valid administrator can retrieve an existing order.
//   2. The ID generated by the View link matches the ID expected
//      by the detail query.
//   3. A known existing order does not incorrectly produce
//      "not found."
//   4. A nonexistent order produces the proper not-found state.
//   5. A database failure is not misreported as a missing order.
//   6. Missing optional fields do not crash the page.
//   7. An order with multiple items renders correctly.
//   8. An unauthorized customer cannot access admin details.
//   9. An invalid status transition is rejected.
//  10. A valid order-confirmation action persists successfully.
//  11. A status-update failure does not falsely display success.
//  12. Existing orders and historical totals remain unchanged.
//
// All of these tests are MOCKED. The live equivalents run against
// the configured Supabase project in
// `admin-order-detail.live.test.mjs`.
//
// The tests in this file exercise the data layer (`getOrderForAdmin`
// and friends) and the action layer (`updateOrderStatusAction`).
// The actual Next.js page module is a server component; we don't
// render it here because doing so would require a Next.js
// runtime, but the data the page consumes comes from the functions
// we test below, and the page has been smoke-tested against the
// live backend in the live suite.

import { test, beforeEach } from "node:test";
import assert from "node:assert/strict";

// The service module reads the service client via the
// `__setServiceClientForTesting` injection point so the mock can
// drive its queries deterministically.
import {
  __setServiceClientForTesting,
} from "@/lib/orders/service.ts";
import { __setCurrentUserForTesting } from "@/lib/auth/require.ts";
import { createMockSupabaseClient } from "./fixtures/mock-supabase.mjs";
import {
  getOrderForAdmin,
  listOrdersForAdmin,
  updateOrderStatus,
  updatePaymentStatus,
} from "@/lib/orders/server";

const ADMIN_USER = {
  id: "admin-1",
  email: "admin@monoform.test",
};
const CUSTOMER_USER = {
  id: "customer-1",
  email: "customer@monoform.test",
};

function adminAllowlist() {
  return [{ user_id: ADMIN_USER.id }];
}

function baseOrder(overrides = {}) {
  return {
    id: "c9fb8025-ea10-4b00-a969-59237e6e9a64",
    order_number: "MF-000007",
    created_at: "2026-10-13T06:54:19.35247+00:00",
    order_status: "pending_confirmation",
    payment_method: "cod",
    payment_status: "pending",
    subtotal_paisa: 2450000,
    delivery_fee_paisa: 7000,
    total_paisa: 2457000,
    currency: "BDT",
    customer_name: "Al Jubaer Hussain",
    customer_phone: "01990421055",
    customer_email: "jubaerh662@gmail.com",
    recipient_name: "Al Jubaer Hussain",
    phone: "01990421055",
    district: "Dhaka",
    locality: null,
    address_line: "18",
    additional_details: null,
    postal_code: "1216",
    delivery_zone: "inside_dhaka",
    delivery_instructions: null,
    bkash_reference: null,
    cancelled_at: null,
    ...overrides,
  };
}

function baseItem(overrides = {}) {
  return {
    id: "item-1",
    order_id: "c9fb8025-ea10-4b00-a969-59237e6e9a64",
    product_id: "p-001",
    product_slug: "wool-overcoat-camel",
    product_name: "Wool Overcoat",
    size: "M",
    color: "Camel",
    quantity: 1,
    unit_price_paisa: 2450000,
    line_total_paisa: 2450000,
    image_alt: "Wool overcoat, front view",
    image_aspect_ratio: 0.75,
    created_at: "2026-10-13T06:54:20.177793+00:00",
    ...overrides,
  };
}

let mock;

beforeEach(() => {
  mock = null;
  __setServiceClientForTesting(null);
  __setCurrentUserForTesting(null);
});

test("scenario 1: a valid administrator can retrieve an existing order", async () => {
  __setCurrentUserForTesting(ADMIN_USER);
  mock = createMockSupabaseClient({
    user: ADMIN_USER,
    allowlist: adminAllowlist(),
  });
  __setServiceClientForTesting(mock);
  // requireAdmin() -> allowlist lookup
  mock.__push("admin_allowlist", "select", {
    data: { user_id: ADMIN_USER.id },
    error: null,
  });
  // readOrderAsAdminDetail orders -> success
  mock.__push("orders", "select", { data: baseOrder(), error: null });
  // fetchItems
  mock.__push("order_items", "select", { data: [baseItem()], error: null });
  // fetchTimeline
  mock.__push("order_status_history", "select", { data: [], error: null });
  // notifications
  mock.__push("order_notifications", "select", { data: [], error: null });

  const result = await getOrderForAdmin(baseOrder().id);
  assert.equal(result.kind, "ok");
  if (result.kind !== "ok") return;
  assert.equal(result.order.id, baseOrder().id);
  assert.equal(result.order.number, "MF-000007");
  assert.equal(result.order.customerName, "Al Jubaer Hussain");
  assert.equal(result.order.itemCount, 1);
  assert.equal(result.order.total.amount, 24570);
});

test("scenario 2: the ID in the View link is the same UUID the detail query expects", async () => {
  __setCurrentUserForTesting(ADMIN_USER);

  // Phase 1: the list page.
  const listMock = createMockSupabaseClient({
    user: ADMIN_USER,
    allowlist: adminAllowlist(),
  });
  __setServiceClientForTesting(listMock);
  listMock.__push("admin_allowlist", "select", {
    data: { user_id: ADMIN_USER.id },
    error: null,
  });
  listMock.__push("orders", "select", {
    data: [baseOrder()],
    error: null,
  });
  // countItemsForOrder: empty items
  listMock.__push("order_items", "select", { data: [], error: null });

  const list = await listOrdersForAdmin();
  assert.equal(list.kind, "ok");
  if (list.kind !== "ok") return;
  const viewId = list.orders[0].id;
  assert.equal(viewId, baseOrder().id);

  // Phase 2: the detail page. Use a fresh mock so the two
  // halves don't share queued responses.
  const detailMock = createMockSupabaseClient({
    user: ADMIN_USER,
    allowlist: adminAllowlist(),
  });
  __setServiceClientForTesting(detailMock);
  detailMock.__push("admin_allowlist", "select", {
    data: { user_id: ADMIN_USER.id },
    error: null,
  });
  detailMock.__push("orders", "select", {
    data: baseOrder({ id: viewId }),
    error: null,
  });
  detailMock.__push("order_items", "select", {
    data: [baseItem({ order_id: viewId })],
    error: null,
  });
  detailMock.__push("order_status_history", "select", { data: [], error: null });
  detailMock.__push("order_notifications", "select", { data: [], error: null });

  const detail = await getOrderForAdmin(viewId);
  assert.equal(detail.kind, "ok");
  if (detail.kind !== "ok") return;
  assert.equal(detail.order.id, viewId);
});

test("scenario 3: a known existing order does NOT produce 'not_found'", async () => {
  __setCurrentUserForTesting(ADMIN_USER);
  mock = createMockSupabaseClient({ user: ADMIN_USER, allowlist: adminAllowlist() });
  __setServiceClientForTesting(mock);
  mock.__push("admin_allowlist", "select", { data: { user_id: ADMIN_USER.id }, error: null });
  mock.__push("orders", "select", { data: baseOrder(), error: null });
  mock.__push("order_items", "select", { data: [baseItem()], error: null });
  mock.__push("order_status_history", "select", { data: [], error: null });
  mock.__push("order_notifications", "select", { data: [], error: null });

  const result = await getOrderForAdmin(baseOrder().id);
  assert.notEqual(result.kind, "not_found");
  assert.equal(result.kind, "ok");
});

test("scenario 4: a nonexistent UUID produces not_found (not error)", async () => {
  __setCurrentUserForTesting(ADMIN_USER);
  mock = createMockSupabaseClient({ user: ADMIN_USER, allowlist: adminAllowlist() });
  __setServiceClientForTesting(mock);
  mock.__push("admin_allowlist", "select", { data: { user_id: ADMIN_USER.id }, error: null });
  mock.__push("orders", "select", { data: null, error: null });

  const result = await getOrderForAdmin("aaaaaaaa-bbbb-cccc-dddd-eeeeeeeeeeee");
  assert.equal(result.kind, "not_found");
});

test("scenario 4b: a non-UUID id is rejected before any DB call", async () => {
  __setCurrentUserForTesting(ADMIN_USER);
  mock = createMockSupabaseClient({ user: ADMIN_USER, allowlist: adminAllowlist() });
  __setServiceClientForTesting(mock);
  mock.__push("admin_allowlist", "select", { data: { user_id: ADMIN_USER.id }, error: null });

  const result = await getOrderForAdmin("MF-000007");
  assert.equal(result.kind, "not_found");
  // The mock should not have received any orders query
  const ordersCalls = mock.__getCalls().filter((c) => c.table === "orders");
  assert.equal(ordersCalls.length, 0, "non-UUID ids must not hit the database");
});

test("scenario 5: a database failure is reported as 'error', NOT as 'not_found'", async () => {
  __setCurrentUserForTesting(ADMIN_USER);
  mock = createMockSupabaseClient({ user: ADMIN_USER, allowlist: adminAllowlist() });
  __setServiceClientForTesting(mock);
  mock.__push("admin_allowlist", "select", { data: { user_id: ADMIN_USER.id }, error: null });
  mock.__push("orders", "select", {
    data: null,
    error: { code: "42P01", message: "relation does not exist" },
  });

  const result = await getOrderForAdmin(baseOrder().id);
  assert.equal(result.kind, "error", "a database error must surface as 'error', not 'not_found'");
});

test("scenario 6: missing optional fields do not crash the row→detail mapping", async () => {
  __setCurrentUserForTesting(ADMIN_USER);
  mock = createMockSupabaseClient({ user: ADMIN_USER, allowlist: adminAllowlist() });
  __setServiceClientForTesting(mock);
  // All optional fields null; recipient fields empty.
  mock.__push("admin_allowlist", "select", { data: { user_id: ADMIN_USER.id }, error: null });
  mock.__push("orders", "select", {
    data: baseOrder({
      locality: null,
      additional_details: null,
      delivery_instructions: null,
      bkash_reference: null,
      customer_email: null,
      customer_phone: null,
    }),
    error: null,
  });
  mock.__push("order_items", "select", { data: [], error: null });
  mock.__push("order_status_history", "select", { data: [], error: null });
  mock.__push("order_notifications", "select", { data: [], error: null });

  const result = await getOrderForAdmin(baseOrder().id);
  assert.equal(result.kind, "ok");
  if (result.kind !== "ok") return;
  assert.equal(result.order.items.length, 0);
  assert.equal(result.order.itemCount, 0);
  assert.equal(result.customerEmail, null);
  assert.equal(result.order.shippingAddress.locality, null);
  assert.equal(result.order.shippingAddress.deliveryInstructions, null);
  assert.equal(result.order.paymentReference, null);
});

test("scenario 7: an order with multiple items aggregates the line quantities", async () => {
  __setCurrentUserForTesting(ADMIN_USER);
  mock = createMockSupabaseClient({ user: ADMIN_USER, allowlist: adminAllowlist() });
  __setServiceClientForTesting(mock);
  mock.__push("admin_allowlist", "select", { data: { user_id: ADMIN_USER.id }, error: null });
  mock.__push("orders", "select", { data: baseOrder(), error: null });
  mock.__push("order_items", "select", {
    data: [
      baseItem({ id: "i1", product_name: "Wool Overcoat", quantity: 1, line_total_paisa: 2450000 }),
      baseItem({ id: "i2", product_name: "Linen Shirt", size: "L", color: "Ivory", quantity: 2, unit_price_paisa: 180000, line_total_paisa: 360000 }),
    ],
    error: null,
  });
  mock.__push("order_status_history", "select", { data: [], error: null });
  mock.__push("order_notifications", "select", { data: [], error: null });

  const result = await getOrderForAdmin(baseOrder().id);
  assert.equal(result.kind, "ok");
  if (result.kind !== "ok") return;
  assert.equal(result.order.items.length, 2);
  assert.equal(result.order.itemCount, 3, "itemCount must be the sum of line quantities");
});

test("scenario 8: an unauthorized customer cannot access admin details", async () => {
  __setCurrentUserForTesting(CUSTOMER_USER);
  mock = createMockSupabaseClient({ user: CUSTOMER_USER, allowlist: [] });
  __setServiceClientForTesting(mock);
  // requireAdmin() -> allowlist lookup returns nothing
  mock.__push("admin_allowlist", "select", { data: null, error: null });

  const result = await getOrderForAdmin(baseOrder().id);
  assert.equal(result.kind, "forbidden");
  // No order query should have been issued.
  const ordersCalls = mock.__getCalls().filter((c) => c.table === "orders");
  assert.equal(ordersCalls.length, 0, "forbidden customers must not reach the orders table");
});

test("scenario 8b: an unauthenticated visitor cannot access admin details", async () => {
  __setCurrentUserForTesting(null);
  mock = createMockSupabaseClient({ user: null, allowlist: [] });
  __setServiceClientForTesting(mock);

  const result = await getOrderForAdmin(baseOrder().id);
  assert.equal(result.kind, "not_authenticated");
});

test("scenario 9: an invalid status transition is rejected", async () => {
  __setCurrentUserForTesting(ADMIN_USER);
  mock = createMockSupabaseClient({ user: ADMIN_USER, allowlist: adminAllowlist() });
  __setServiceClientForTesting(mock);
  mock.__push("admin_allowlist", "select", { data: { user_id: ADMIN_USER.id }, error: null });
  // existing order lookup
  mock.__push("orders", "select", {
    data: { id: baseOrder().id, order_status: "delivered" },
    error: null,
  });

  // pending_confirmation → delivered is NOT a valid single-step transition.
  const result = await updateOrderStatus({
    orderId: baseOrder().id,
    nextStatus: "pending_confirmation",
  });
  assert.notEqual(result.kind, "ok");
  assert.equal(result.kind, "invalid_transition");
});

test("scenario 10: a valid order-confirmation (pending → confirmed) persists", async () => {
  __setCurrentUserForTesting(ADMIN_USER);
  mock = createMockSupabaseClient({ user: ADMIN_USER, allowlist: adminAllowlist() });
  __setServiceClientForTesting(mock);
  mock.__push("admin_allowlist", "select", { data: { user_id: ADMIN_USER.id }, error: null });
  // existing
  mock.__push("orders", "select", {
    data: { id: baseOrder().id, order_status: "pending_confirmation" },
    error: null,
  });
  // update succeeds
  mock.__push("orders", "update", { data: null, error: null });
  // status history insert
  mock.__push("order_status_history", "insert", { data: null, error: null });
  // detail re-read: orders
  mock.__push("orders", "select", {
    data: baseOrder({ order_status: "confirmed" }),
    error: null,
  });
  // detail re-read: items
  mock.__push("order_items", "select", { data: [baseItem()], error: null });
  // detail re-read: timeline
  mock.__push("order_status_history", "select", { data: [], error: null });
  // detail re-read: notifications
  mock.__push("order_notifications", "select", { data: [], error: null });

  const result = await updateOrderStatus({
    orderId: baseOrder().id,
    nextStatus: "confirmed",
  });
  assert.equal(result.kind, "ok");
  if (result.kind !== "ok") return;
  assert.equal(result.order.status, "confirmed");
  // Exactly one orders.update was issued.
  const updates = mock
    .__getCalls()
    .filter((c) => c.table === "orders" && c.op === "update");
  assert.equal(updates.length, 1);
});

test("scenario 11: a status-update DB failure does NOT falsely report success", async () => {
  __setCurrentUserForTesting(ADMIN_USER);
  mock = createMockSupabaseClient({ user: ADMIN_USER, allowlist: adminAllowlist() });
  __setServiceClientForTesting(mock);
  mock.__push("admin_allowlist", "select", { data: { user_id: ADMIN_USER.id }, error: null });
  mock.__push("orders", "select", {
    data: { id: baseOrder().id, order_status: "pending_confirmation" },
    error: null,
  });
  // The update itself fails.
  mock.__push("orders", "update", {
    data: null,
    error: { code: "08006", message: "connection lost" },
  });

  const result = await updateOrderStatus({
    orderId: baseOrder().id,
    nextStatus: "confirmed",
  });
  assert.notEqual(result.kind, "ok", "a failed update must not report success");
});

test("scenario 12: existing orders retain their historical totals through re-reads", async () => {
  __setCurrentUserForTesting(ADMIN_USER);
  const original = baseOrder();
  // First read.
  const mock1 = createMockSupabaseClient({ user: ADMIN_USER, allowlist: adminAllowlist() });
  __setServiceClientForTesting(mock1);
  mock1.__push("admin_allowlist", "select", { data: { user_id: ADMIN_USER.id }, error: null });
  mock1.__push("orders", "select", { data: original, error: null });
  mock1.__push("order_items", "select", { data: [baseItem()], error: null });
  mock1.__push("order_status_history", "select", { data: [], error: null });
  mock1.__push("order_notifications", "select", { data: [], error: null });

  const r1 = await getOrderForAdmin(original.id);
  assert.equal(r1.kind, "ok");
  if (r1.kind !== "ok") return;
  const snapshot = {
    subtotal: r1.order.subtotal.amount,
    delivery: r1.order.deliveryFee.amount,
    total: r1.order.total.amount,
    currency: r1.order.total.currency,
  };
  assert.equal(snapshot.subtotal, 24500);
  assert.equal(snapshot.delivery, 70);
  assert.equal(snapshot.total, 24570);
  assert.equal(snapshot.currency, "BDT");

  // Re-read with a fresh mock; values must be identical.
  const mock2 = createMockSupabaseClient({ user: ADMIN_USER, allowlist: adminAllowlist() });
  __setServiceClientForTesting(mock2);
  mock2.__push("admin_allowlist", "select", { data: { user_id: ADMIN_USER.id }, error: null });
  mock2.__push("orders", "select", { data: original, error: null });
  mock2.__push("order_items", "select", { data: [baseItem()], error: null });
  mock2.__push("order_status_history", "select", { data: [], error: null });
  mock2.__push("order_notifications", "select", { data: [], error: null });

  const r2 = await getOrderForAdmin(original.id);
  assert.equal(r2.kind, "ok");
  if (r2.kind !== "ok") return;
  assert.equal(r2.order.subtotal.amount, snapshot.subtotal);
  assert.equal(r2.order.deliveryFee.amount, snapshot.delivery);
  assert.equal(r2.order.total.amount, snapshot.total);
  assert.equal(r2.order.total.currency, snapshot.currency);
});

test("scenario 12b: payment status is preserved across reads (COD pending → read → still pending)", async () => {
  __setCurrentUserForTesting(ADMIN_USER);
  mock = createMockSupabaseClient({ user: ADMIN_USER, allowlist: adminAllowlist() });
  __setServiceClientForTesting(mock);
  mock.__push("admin_allowlist", "select", { data: { user_id: ADMIN_USER.id }, error: null });
  mock.__push("orders", "select", { data: baseOrder(), error: null });
  mock.__push("order_items", "select", { data: [baseItem()], error: null });
  mock.__push("order_status_history", "select", { data: [], error: null });
  mock.__push("order_notifications", "select", { data: [], error: null });

  const result = await getOrderForAdmin(baseOrder().id);
  assert.equal(result.kind, "ok");
  if (result.kind !== "ok") return;
  assert.equal(result.order.paymentMethod, "cod");
  assert.equal(result.order.paymentStatus, "pending");
});

test("scenario 8c: a payment status update on a COD order can set 'paid'", async () => {
  __setCurrentUserForTesting(ADMIN_USER);
  mock = createMockSupabaseClient({ user: ADMIN_USER, allowlist: adminAllowlist() });
  __setServiceClientForTesting(mock);
  mock.__push("admin_allowlist", "select", { data: { user_id: ADMIN_USER.id }, error: null });
  mock.__push("orders", "select", {
    data: {
      id: baseOrder().id,
      payment_method: "cod",
      payment_status: "pending",
    },
    error: null,
  });
  mock.__push("orders", "update", { data: null, error: null });
  mock.__push("order_status_history", "insert", { data: null, error: null });
  // detail re-read
  mock.__push("orders", "select", {
    data: baseOrder({ payment_status: "paid" }),
    error: null,
  });
  mock.__push("order_items", "select", { data: [baseItem()], error: null });
  mock.__push("order_status_history", "select", { data: [], error: null });
  mock.__push("order_notifications", "select", { data: [], error: null });

  const result = await updatePaymentStatus({
    orderId: baseOrder().id,
    nextStatus: "paid",
  });
  assert.equal(result.kind, "ok");
  if (result.kind !== "ok") return;
  assert.equal(result.order.paymentStatus, "paid");
});
